impl SseEncode for spr_mobile::Operation {
    // Codec=Sse (Serialization based), see doc to use other codecs
    fn sse_encode(self, serializer: &mut flutter_rust_bridge::for_generated::SseSerializer) {
        match self {
            spr_mobile::Operation::Registration => {
                <i32>::sse_encode(0, serializer);
            }
            spr_mobile::Operation::Deposit {
                mint,
                amount,
                creates_spl_interface,
            } => {
                <i32>::sse_encode(1, serializer);
                <Option<String>>::sse_encode(mint, serializer);
                <u64>::sse_encode(amount, serializer);
                <bool>::sse_encode(creates_spl_interface, serializer);
            }
            spr_mobile::Operation::Spend {
                mint,
                outputs,
                created_token_accounts,
            } => {
                <i32>::sse_encode(2, serializer);
                <Option<String>>::sse_encode(mint, serializer);
                <Vec<spr_mobile::Output>>::sse_encode(outputs, serializer);
                <Vec<String>>::sse_encode(created_token_accounts, serializer);
            }
            spr_mobile::Operation::Merging { enabled } => {
                <i32>::sse_encode(3, serializer);
                <bool>::sse_encode(enabled, serializer);
            }
            spr_mobile::Operation::Merge { mint, amount } => {
                <i32>::sse_encode(4, serializer);
                <Option<String>>::sse_encode(mint, serializer);
                <u64>::sse_encode(amount, serializer);
            }
            spr_mobile::Operation::Custom { programs } => {
                <i32>::sse_encode(5, serializer);
                <Vec<String>>::sse_encode(programs, serializer);
            }
            _ => {
                unimplemented!("");
            }
        }
    }
}

